/**
 * @brief 名前から圧縮PCMサンプルを取得する
 * @param name サンプル名
 * @return 該当サンプル、存在しない場合nullptr
 */
inline const WavData* Find(std::string_view name) {
    for (const auto& item : SAMPLES) {
        if (name == item.name) return &item;
    }
    return nullptr;
}

/**
 * @brief 差分圧縮された8bit PCMを復号する
 * @param sample 圧縮PCMサンプル
 * @param output 復号先
 * @return 復号に成功した場合true
 */
inline bool Decode(const WavData& sample, std::vector<std::uint8_t>& output) {
    if (!sample.data || sample.byteCount == 0 || sample.sampleCount == 0) return false;

    // 先頭値を基準に4bit差分を順次復号する
    output.resize(sample.sampleCount);
    output[0] = sample.data[0];
    std::size_t bitOffset = 0;
    const auto ReadBits = [&](unsigned count, std::uint32_t& value) {
        if (bitOffset + count > (sample.byteCount - 1) * 8) return false;
        value = 0;
        for (unsigned bit = 0; bit < count; ++bit) {
            const std::size_t sourceBit = bitOffset + bit;
            value |= ((sample.data[1 + sourceBit / 8] >> (sourceBit % 8)) & 1u) << bit;
        }
        bitOffset += count;
        return true;
    };

    for (std::size_t i = 1; i < sample.sampleCount; ++i) {
        std::uint32_t code = 0;
        if (!ReadBits(4, code)) return false;
        if (code == 15) {
            if (!ReadBits(8, code)) return false;
            output[i] = static_cast<std::uint8_t>(code);
            continue;
        }
        const int value = static_cast<int>(output[i - 1]) + (static_cast<int>(code) - 7) * 4;
        if (value < 0 || value > 255) return false;
        output[i] = static_cast<std::uint8_t>(value);
    }
    return true;
}

